package pl.zagranietyper.parser;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class FootballEventPlayerPositiveSyntaxAdapterTest {private final FootballEventPlayerPositiveSyntaxAdapter p=new FootballEventPlayerPositiveSyntaxAdapter();@Test void acceptsPureWholeTitles(){assertTrue(p.parse("M. Salah strzeli gola").parsed());assertTrue(p.parse("Salah z golem").parsed());assertTrue(p.parse("J. Murphy zaliczy asystę").parsed());}@Test void rejectsFirstTimedCountCompositeAndPartial(){assertFalse(p.parse("Pierwszy gol: M. Salah").parsed());assertFalse(p.parse("M. Salah strzeli gola do 30 min").parsed());assertFalse(p.parse("M. Salah strzeli 2 gole").parsed());assertFalse(p.parse("M. Salah strzeli gola lub zaliczy asystę").parsed());assertFalse(p.parse("Liverpool wygra i M. Salah strzeli gola").parsed());}}
